style.css:
@-moz-document url-prefix("https://www.google.com/search"), url-prefix("https://www.google.com/webhp") {
/* Base background and text */
  html, body {
    background: #141414 !important;
    color: #ffffff !important;
  }

  /* General containers */
  .MjjYud, .tF2Cxc, .g, .hlcw0c, .kvH3mc, .yuRUbf, .N54PNb, .BVG0Nb, .ULSxyf,
  .xpdopen, .xpd, .nGphre, .zCubwf, .Gx5Zad, .kno-fb-ctx, .kp-wholepage, .kp-blk,
  .xpdopen, .xpd, .ZINbbc, .BVG0Nb, .rl_full, .wDYxhc, .sATSHe, .uU7dJb,
  .c2xzTb, .v7W49e, .mnr-c, .s6JM6d, .u0Ymc, .EaH1Gc, .VwiC3b, .vBjznb,
  .MUxGbd, .BVG0Nb, .FozYP, .Ww4FFb, .zXETZb, .Z26q7c {
    background-color: #141414 !important;
  }

  /* Links */
  a {
    color: #a60f2d !important;
    transition: color 0.3s !important;
  }

  a:hover {
    color: #c81e3c !important;
  }

  /* Input fields */
  input[type="text"],
  input[type="search"] {
    background: #282828 !important;
    color: #ffffff !important;
    border: 1px solid #a60f2d !important;
    transition: box-shadow 0.3s, border 0.3s !important;
  }

  input[type="text"]:focus,
  input[type="search"]:focus {
    outline: none !important;
    box-shadow: 0 0 0 2px #c81e3c !important;
  }

  input[type="submit"],
  button {
    background: #a60f2d !important;
    color: #ffffff !important;
    border: none !important;
    transition: background 0.3s, color 0.3s !important;
  }

  input[type="submit"]:hover,
  button:hover {
    background: #c81e3c !important;
  }

  /* Search form area */
  #searchform,
  .tsf,
  .A8SBwf,
  .RNNXgb,
  .SDkEP,
  .sfbg {
    background: #141414 !important;
  }

  /* Top navigation tabs (All, Images, etc.) */
  .hdtb-mitem a {
    background: #141414 !important;
    color: #ffffff !important;
    transition: color 0.3s, border-bottom 0.3s !important;
  }

  .hdtb-mitem.hdtb-msel a,
  .hdtb-mitem a:hover {
    color: #a60f2d !important;
    border-bottom: 2px solid #a60f2d !important;
  }

  /* Cards and featured snippets */
  .xpd, .xpdopen, .ifM9O, .BVG0Nb, .ULSxyf, .xpd, .zCubwf, .uUPGi, .kp-blk,
  .VkpGBb, .rllt__details, .cLjAic, .mnr-c, .kno-rdesc, .rhs, .rhscol, .kp-wholepage {
    background-color: #141414 !important;
  }

  /* Footer */
  #fbar, footer {
    background: #141414 !important;
    color: #ffffff !important;
  }
}
